/**

 * Generate src/price-tick-browser.js from services/price-tick.js + futures-contract-specs.

 * Run: node scripts/generate-price-tick-browser.js

 */

const fs = require('fs');

const path = require('path');



const ROOT = path.join(__dirname, '..');

const { RAW_SPECS } = require('../services/futures-contract-specs');

const { EXCHANGE_DEFAULT_TICK, DEFAULT_TICK } = require('../services/price-tick');



const tickMap = Object.fromEntries(

  Object.entries(RAW_SPECS).map(([id, raw]) => [id, raw.tickSize])

);



const out = `/**

 * Browser bundle — auto-generated by scripts/generate-price-tick-browser.js

 * DO NOT EDIT; run the generator after changing futures-contract-specs.js

 */

(function (global) {

  const TICK_MAP = ${JSON.stringify(tickMap, null, 2)};

  const EXCHANGE_DEFAULT_TICK = ${JSON.stringify(EXCHANGE_DEFAULT_TICK, null, 2)};

  const DEFAULT_TICK = ${DEFAULT_TICK};



  function getTickDecimals(tick) {

    if (tick == null || tick >= 1) return 0;

    const frac = String(tick).split('.')[1];

    return frac ? frac.length : 2;

  }



  function getTickSize(instrumentId) {

    const id = String(instrumentId || '').toLowerCase();

    const mapped = TICK_MAP[id];

    if (mapped > 0) return mapped;

    return DEFAULT_TICK;

  }



  function roundPriceToTick(instrumentId, price) {

    if (price == null || Number.isNaN(Number(price))) return null;

    const tick = getTickSize(instrumentId);

    const v = Number(price);

    const rounded = Math.round(v / tick) * tick;

    return +rounded.toFixed(getTickDecimals(tick));

  }



  function isValidTickPrice(instrumentId, price) {

    if (price == null || Number.isNaN(Number(price))) return false;

    const rounded = roundPriceToTick(instrumentId, price);

    return rounded != null && Math.abs(Number(price) - rounded) < 1e-9;

  }



  function looksLikePctBand(high, low, baseClose) {

    const base = Number(baseClose);

    const hi = Number(high);

    const lo = Number(low);

    if ([base, hi, lo].some((v) => v == null || Number.isNaN(v)) || base <= 0) return false;

    if (Math.abs(hi) > 25 || Math.abs(lo) > 25) return false;

    return Math.abs(hi) < base * 0.02 && Math.abs(lo) < base * 0.02;

  }



  function pctBandToPrices({ instrumentId, baseClose, lowPct, highPct }) {

    const base = Number(baseClose);

    if (!base || base <= 0) return { predictedHigh: null, predictedLow: null };

    const loPct = Number(lowPct);

    const hiPct = Number(highPct);

    if ([loPct, hiPct].some((v) => Number.isNaN(v))) {

      return { predictedHigh: null, predictedLow: null };

    }

    const rawLo = base * (1 + loPct / 100);

    const rawHi = base * (1 + hiPct / 100);

    return {

      predictedLow: roundPriceToTick(instrumentId, Math.min(rawLo, rawHi)),

      predictedHigh: roundPriceToTick(instrumentId, Math.max(rawLo, rawHi)),

    };

  }



  function formatPriceForInstrument(instrumentId, price) {

    if (price == null || Number.isNaN(Number(price))) return '—';

    const v = roundPriceToTick(instrumentId, price);

    if (v == null) return '—';

    const tick = getTickSize(instrumentId);

    if (tick >= 1) return String(Math.round(v));

    return v.toFixed(getTickDecimals(tick));

  }



  global.PriceTick = {

    TICK_MAP,

    EXCHANGE_DEFAULT_TICK,

    DEFAULT_TICK,

    getTickSize,

    getTickDecimals,

    roundPriceToTick,

    isValidTickPrice,

    looksLikePctBand,

    pctBandToPrices,

    formatPriceForInstrument,

  };

})(typeof window !== 'undefined' ? window : globalThis);

`;



const dest = path.join(ROOT, 'src', 'price-tick-browser.js');

fs.writeFileSync(dest, out, 'utf8');

console.log('Wrote', dest, '—', Object.keys(tickMap).length, 'instruments');


